const aiResponse = $input.item.json.choices[0].message.content;
try {
  // Remove markdown code fences if present
  let cleanedResponse = aiResponse.trim();

  // Remove opening code fence (```json or ```)
  cleanedResponse = cleanedResponse.replace(/^```(?:json)?\n?/, '');

  // Remove closing code fence (```)
  cleanedResponse = cleanedResponse.replace(/\n?```$/, '');

  // Parse the cleaned JSON
  const parsed = JSON.parse(cleanedResponse.trim());
  return [{ json: parsed }];
} catch (e) {
  // If parsing fails, return error object with raw response
  return [{ json: { status: "ERROR", reason: aiResponse } }];
}

// Transform Turso response from columns+rows format to JSON objects
const tursoResponse = $input.first().json;
const columns = tursoResponse.results.columns;
const rows = tursoResponse.results.rows;

// Map each row to an object with column names as keys
const transformedData = rows.map(row => {
  const obj = {};
  columns.forEach((column, index) => {
    obj[column] = row[index];
  });
  return obj;
});

// Return the transformed data
return transformedData.map(item => ({ json: item }));

